code:
def should_split_funcdef_with_rhs(line: Line, mode: Mode) -> bool:
    """If a funcdef has a magic trailing comma in the return type, then we should first
    split the line with rhs to respect the comma.
    """
    return_type_leaves: list[Leaf] = []
    in_return_type = False

    for leaf in line.leaves:
        if leaf.type == token.COLON:
            in_return_type = False
        if in_return_type:
            return_type_leaves.append(leaf)
        if leaf.type == token.RARROW:
            in_return_type = True

    # using `bracket_split_build_line` will mess with whitespace, so we duplicate a
    # couple lines from it.
    result = Line(mode=line.mode, depth=line.depth)
    leaves_to_track = get_leaves_inside_matching_brackets(return_type_leaves)
    for leaf in return_type_leaves:
        result.append(
            leaf,
            preformatted=True,
            track_bracket=id(leaf) in leaves_to_track,
        )

    first_visible_return_leaf = next(
        (leaf for leaf in return_type_leaves if leaf.value), None
    )
    return result.magic_trailing_comma is not None or (
        first_visible_return_leaf is not None
        and first_visible_return_leaf.type == token.STRING
        and not is_line_short_enough(result, mode=mode)
    )

def get_git_tags(include_pre: bool = False) -> list[str]:
    """List all git version tags"""
    cp = run(["git", "tag"], capture_output=True, check=True, encoding="utf8")
    if not cp.stdout:
        LOG.error(f"Returned no git tags; stderr: {cp.stderr}")
        raise NoGitTagsError
    git_tags = cp.stdout.splitlines()
    return sorted(
        (t for t in git_tags if is_valid_version(t, include_pre)),
        key=Version,
        reverse=True,
    )

def enable_unstable_feature_callback(
    c: click.Context, p: click.Option | click.Parameter, v: tuple[str, ...]
) -> list[Preview]:
    """Compute the features from an --enable-unstable-feature flag."""
    return [Preview[val] for val in v]

def max_delimiter_priority(self, exclude: Iterable[LeafID] = ()) -> Priority:
        """Return the highest priority of a delimiter found on the line.

        Values are consistent with what `is_split_*_delimiter()` return.
        Raises ValueError on no delimiters.
        """
        return max(v for k, v in self.delimiters.items() if k not in exclude)

def edit():
    """Opens an editor with some text in it."""
    MARKER = "# Everything below is ignored\\n"
    message = click.edit(f"\\n\\n{MARKER}")
    if message is not None:
        msg = message.split(MARKER, 1)[0].rstrip("\\n")
        if not msg:
            click.echo("Empty message!")
        else:
            click.echo(f"Message:\\n{msg}")
    else:
        click.echo("You did not enter anything!")

def find_object(self, object_type: type[V]) -> V | None:
        """Finds the closest object of a given type."""
        node: Context | None = self

        while node is not None:
            if isinstance(node.obj, object_type):
                return node.obj

            node = node.parent

        return None

def parse_pyproject_toml(path_config: str) -> dict[str, Any]:
    """Parse a pyproject toml file, pulling out relevant parts for Black.

    If parsing fails, will raise a tomllib.TOMLDecodeError.
    """
    pyproject_toml = _load_toml(path_config)
    config: dict[str, Any] = pyproject_toml.get("tool", {}).get("black", {})
    config = {k.replace("--", "").replace("-", "_"): v for k, v in config.items()}

    if "target_version" not in config:
        inferred_target_version = infer_target_version(pyproject_toml)
        if inferred_target_version is not None:
            config["target_version"] = [v.name.lower() for v in inferred_target_version]

    return config

def failed(self, src: Path, message: BaseException) -> None:
        """Increment the counter for failed reformatting. Write out a message."""
        if (
            isinstance(message, InvalidInput)
            and message.lineno is not None
            and message.column is not None
            and message.context
        ):
            details = message.details or ""
            err(
                f"error: {message.context}: {src}:{message.lineno}:"
                f"{message.column}{details}"
            )
        else:
            err(f"error: cannot format {src}: {message}")
        self.failure_count += 1

def is_complex_subscript(self, leaf: Leaf) -> bool:
        """Return True iff `leaf` is part of a slice with non-trivial exprs."""
        open_lsqb = self.bracket_tracker.get_open_lsqb()
        if open_lsqb is None:
            return False

        subscript_start = open_lsqb.next_sibling

        if isinstance(subscript_start, Node):
            if subscript_start.type == syms.listmaker:
                return False

            if subscript_start.type == syms.subscriptlist:
                subscript_start = child_towards(subscript_start, leaf)

        if subscript_start is None:
            return False

        # The pre_order walk only depends on subscript_start, which is stable
        # while a line is built, so cache it per node. Without this, appending
        # every leaf of a large bracketed expression that holds no TEST_DESCENDANTS
        # node (e.g. a long run of implicitly concatenated strings) re-walks the
        # whole subtree each time, which is quadratic.
        key = id(subscript_start)
        cached = self._complex_subscript_cache.get(key)
        if cached is None:
            cached = any(
                n.type in TEST_DESCENDANTS for n in subscript_start.pre_order()
            )
            self._complex_subscript_cache[key] = cached
        return cached

def is_valid_line_range(lines: tuple[int, int]) -> bool:
    """Returns whether the line range is valid."""
    return lines[0] <= lines[1]

async def schedule_formatting(
    sources: set[Path],
    fast: bool,
    write_back: WriteBack,
    mode: Mode,
    report: Report,
    loop: asyncio.AbstractEventLoop,
    executor: Executor,
    no_cache: bool = False,
    cache_dir: Path | None = None,
) -> None:
    """Run formatting of `sources` in parallel using the provided `executor`.

    (Use ProcessPoolExecutors for actual parallelism.)

    `write_back`, `fast`, and `mode` options are passed to
    :func:`format_file_in_place`.
    """
    if no_cache:
        cache = None
    elif cache_dir is None:
        cache = Cache.read(mode)
    else:
        cache = Cache.read(mode, cache_dir)
    if cache is not None and write_back not in (
        WriteBack.DIFF,
        WriteBack.COLOR_DIFF,
    ):
        sources, cached = cache.filtered_cached(sources)
        for src in sorted(cached):
            report.done(src, Changed.CACHED)
    if not sources:
        return

    cancelled = []
    sources_to_cache = []
    lock = None
    manager = None
    if write_back in (WriteBack.DIFF, WriteBack.COLOR_DIFF):
        # For diff output, we need locks to ensure we don't interleave output
        # from different processes.
        manager = Manager()
        lock = manager.Lock()

    try:
        tasks = {
            asyncio.ensure_future(
                loop.run_in_executor(
                    executor, format_file_in_place, src, fast, mode, write_back, lock
                )
            ): src
            for src in sorted(sources)
        }
        pending = set(tasks)
        try:
            loop.add_signal_handler(signal.SIGINT, cancel, pending)
            loop.add_signal_handler(signal.SIGTERM, cancel, pending)
        except NotImplementedError:
            # There are no good alternatives for these on Windows.
            pass
        # `asyncio.wait(..., return_when=FIRST_COMPLETED)` in a tight loop is
        # quadratic in the number of files: every call re-registers completion
        # callbacks on all pending tasks, so 10x the files means ~100x that
        # bookkeeping (see #1951). A done callback per task costs O(1) per
        # completion instead, and the queue preserves completion-order
        # processing of results.
        finished: asyncio.Queue[asyncio.Future[Any]] = asyncio.Queue()
        for task in pending:
            task.add_done_callback(finished.put_nowait)
        while pending:
            task = await finished.get()
            pending.discard(task)
            src = tasks.pop(task)
            if task.cancelled():
                cancelled.append(task)
            elif exc := task.exception():
                if report.verbose:
                    traceback.print_exception(type(exc), exc, exc.__traceback__)
                report.failed(src, exc)
            else:
                changed = Changed.YES if task.result() else Changed.NO
                # If the file was written back or was successfully checked as
                # well-formatted, store this information in the cache.
                if write_back is WriteBack.YES or (
                    write_back is WriteBack.CHECK and changed is Changed.NO
                ):
                    sources_to_cache.append(src)
                report.done(src, changed)
        if cancelled:
            await asyncio.gather(*cancelled, return_exceptions=True)
        if sources_to_cache and not no_cache and cache is not None:
            cache.write(sources_to_cache)
    finally:
        if manager is not None:
            manager.shutdown()

def make_pass_decorator(
    object_type: type[T], ensure: bool = False
) -> t.Callable[[t.Callable[te.Concatenate[T, P], R]], t.Callable[P, R]]:
    """Given an object type this creates a decorator that will work
    similar to :func:`pass_obj` but instead of passing the object of the
    current context, it will find the innermost context of type
    :func:`object_type`.

    This generates a decorator that works roughly like this::

        from functools import update_wrapper

        def decorator(f):
            @pass_context
            def new_func(ctx, *args, **kwargs):
                obj = ctx.find_object(object_type)
                return ctx.invoke(f, obj, *args, **kwargs)
            return update_wrapper(new_func, f)
        return decorator

    :param object_type: the type of the object to pass.
    :param ensure: if set to `True`, a new object will be created and
                   remembered on the context if it's not there yet.
    """

    def decorator(f: t.Callable[te.Concatenate[T, P], R]) -> t.Callable[P, R]:
        def new_func(*args: P.args, **kwargs: P.kwargs) -> R:
            ctx = get_current_context()

            obj: T | None
            if ensure:
                obj = ctx.ensure_object(object_type)
            else:
                obj = ctx.find_object(object_type)

            if obj is None:
                raise RuntimeError(
                    "Managed to invoke callback without a context"
                    f" object of type {object_type.__name__!r}"
                    " existing."
                )

            return ctx.invoke(f, obj, *args, **kwargs)

        return update_wrapper(new_func, f)

    return decorator

